<script module lang="ts">
/**
 * Modal side sheet (`design/components/drawer.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/drawer.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/dialog'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  agentMember,
  attributes,
  joinSlot,
  modalFocusTarget,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/drawer.module.css'
import Button from '../controls/Button.svelte'

export type DrawerSide = NonNullable<DrawerProps['side']>

export interface DrawerProps {
  children?: Snippet
  /**
   * The ✕'s accessible name, as in Dialog; localized hosts replace the default `Close`.
   */
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * Actions. One primary (`solid`), rightmost; dismiss is outline or ghost.
   */
  footer?: Snippet
  /**
   * The same as Dialog's, from the shared focus code: unset focuses the first tabbable per the
   * focus-order rule, and `dismiss` suits a panel asking whether you meant it.
   */
  initialFocus?: 'primary' | 'dismiss'
  onOpenChange?: (open: boolean) => void
  open?: boolean
  side?: 'start' | 'end' | 'bottom'
  /**
   * Inline size for a start/end sheet, block size for a bottom one. Both derive from the space
   * scale, so a roomier theme gets a larger sheet.
   */
  size?: 'sm' | 'md' | 'lg'
  title: string
}
</script>

<script lang="ts">
let {
  children,
  closeLabel = 'Close',
  defaultOpen,
  description,
  dismissible = true,
  footer,
  initialFocus = 'primary',
  onOpenChange,
  open,
  side = 'end',
  size = 'md',
  title,
}: DrawerProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ size: size }))
const slots = {
  get default() {
    return children
  },
  get footer() {
    return footer
  },
}
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      closeOnEscape: dismissible,
      closeOnInteractOutside: dismissible,
      initialFocusEl: () => modalFocusTarget(panel, initialFocus),
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const scrimPresent = usePresence(
  () => api.open,
  () => scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.open,
  () => panel,
  'drawer.panel',
  {
    get sheetSide() {
      return side
    },
  },
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Drawer',
    element: () => panel,
    state: () => ({ open: api.open }),
    actions: {
      close: () =>
        (() => {
          if (!dismissible) throw new Error('The drawer asks for a choice among its own actions.')
          if (api.open) api.setOpen(false)
        })(),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<Portal
    >{#if scrimPresent.current
      }<div
        bind:this={scrim}
        {...attributes(api.getBackdropProps())}
        class={styles.scrim}
        hidden={undefined}
      ></div
    >{/if
    }{#if panelPresent.current
      }<div {...attributes(api.getPositionerProps())} class={styles.positioner} data-side={side}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.panel}
          hidden={undefined}
          data-side={side}
          data-size={size}
          data-member="drawer"
          ><div class={styles.header}
            ><div class={styles.heading}
              ><h2 {...attributes(api.getTitleProps())} class={styles.title}>{title}</h2
              >{#if description !== undefined
                }<p {...attributes(api.getDescriptionProps())} class={styles.description}
                  >{description
                }</p
              >{/if
            }</div
            >{#if dismissible
              }<div class={styles.close} data-dialog-part="close"
                ><Button
                  variant="ghost"
                  tone="neutral"
                  size="sm"
                  iconOnly={true}
                  icon="close"
                  label={closeLabel}
                  onClick={() => { api.setOpen(false) }}
              /></div
            >{/if
          }</div
          ><div class={styles.body} data-dialog-part="body">{@render children?.()}</div
          >{#if slots.footer
            }<div class={styles.footer} data-dialog-part="footer">{@render footer?.()}</div
          >{/if
        }</div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
